using UnityEngine;
using UnityEngine.InputSystem;
namespace ChemistryLab {
public class LabSafety:MonoBehaviour {
 public bool eyesHurt; float splashUntil; Texture2D splashTexture;
 public bool coat,gloves,goggles,gogglesRaised,irritated; LabSession session; float nextWarning; GameObject wornCoat;
 void Awake(){session=GetComponent<LabSession>();}
 public void Equip(string kind){if(kind=="coat")coat=true;if(kind=="gloves")gloves=true;if(kind=="goggles"){goggles=true;gogglesRaised=false;}session.message=kind=="coat"?"Önlük giyildi.":kind=="gloves"?"Sarı koruyucu eldivenler giyildi.":"Koruyucu gözlük takıldı. G: başına kaldır / tekrar tak.";}
 public void CheckStream(string reagent,Vector3 origin,Vector3 end){if(reagent!="HCl(aq)")return;Vector3 delta=end-origin;if(delta.sqrMagnitude<.001f)return;foreach(var r in Hands()){if(!r||!r.enabled||!r.gameObject.activeInHierarchy)continue;var bounds=r.bounds;bounds.Expand(.025f);if(bounds.IntersectRay(new Ray(origin,delta.normalized),out float distance)&&distance<=delta.magnitude){Contact();break;}}}
 public void Contact(){if(Time.time<nextWarning)return;nextWarning=Time.time+2;if(gloves){session.message="HCl eldivene temas etti. Bu eğitim simülasyonunda el korunuyor.";}else{irritated=true;session.message="ELİN TAHRİŞ OLDU! HCl çıplak ele temas etti. Deneyi durdur ve koruyucu ekipmanını kontrol et.";}}
 Renderer[] Hands(){if(session.xrMode)return session.xrRig.GetComponentsInChildren<SkinnedMeshRenderer>();return session.desktopRig.GetComponent<DesktopLabController>().hand.GetComponentsInChildren<Renderer>();}
 void LateUpdate(){var k=Keyboard.current;if(k!=null&&k.gKey.wasPressedThisFrame&&goggles)gogglesRaised=!gogglesRaised;Color tint=gloves?new Color(1,.73f,.04f):irritated?new Color(.9f,.16f,.13f):new Color(.72f,.53f,.4f);foreach(var r in Hands())if(r){foreach(var m in r.materials){if(m.HasProperty("_BaseColor"))m.SetColor("_BaseColor",tint);if(m.HasProperty("_Color"))m.SetColor("_Color",tint);}}
 if(coat&&Camera.main){if(!wornCoat){wornCoat=GameObject.CreatePrimitive(PrimitiveType.Cube);wornCoat.name="Worn laboratory coat";Destroy(wornCoat.GetComponent<Collider>());wornCoat.GetComponent<Renderer>().material.color=new Color(.92f,.94f,.95f);}wornCoat.transform.position=Camera.main.transform.position-Vector3.up*.68f;wornCoat.transform.rotation=Quaternion.Euler(0,Camera.main.transform.eulerAngles.y,0);wornCoat.transform.localScale=new Vector3(.42f,.62f,.22f);}}
 public void OnReaction(){if(goggles&&!gogglesRaised)return;eyesHurt=true;splashUntil=Time.time+2.5f;session.message+="\nGÖZLERİN ZARAR GÖRDÜ! Koruyucu gözlük takılı değildi. (Eğitsel simülasyon)";}
 public void ClearIrritation(){irritated=false;eyesHurt=false;splashUntil=0;nextWarning=0;}
 void OnGUI(){var old=GUI.color;var matrix=GUI.matrix;GUI.matrix=Matrix4x4.identity;if(goggles&&!gogglesRaised){GUI.color=new Color(.55f,.85f,.9f,.055f);GUI.DrawTexture(new Rect(0,0,Screen.width,Screen.height),Texture2D.whiteTexture);GUI.color=new Color(.04f,.08f,.1f,.7f);float w=Screen.width,h=Screen.height;GUI.DrawTexture(new Rect(0,0,w,h*.035f),Texture2D.whiteTexture);GUI.DrawTexture(new Rect(0,h*.94f,w,h*.06f),Texture2D.whiteTexture);GUI.DrawTexture(new Rect(0,0,w*.025f,h),Texture2D.whiteTexture);GUI.DrawTexture(new Rect(w*.975f,0,w*.025f,h),Texture2D.whiteTexture);GUI.DrawTexture(new Rect(w*.49f,h*.035f,w*.02f,h*.10f),Texture2D.whiteTexture);}GUI.color=Color.white;GUI.Label(new Rect(18,90,390,28),"Önlük: "+(coat?"✓":"—")+"   Eldiven: "+(gloves?"✓":"—")+"   Gözlük: "+(!goggles?"—":gogglesRaised?"başta [G]":"takılı [G]"));DrawEyeSplash();GUI.color=old;GUI.matrix=matrix;}
 void DrawEyeSplash(){if(!eyesHurt)return;if(!splashTexture){splashTexture=new Texture2D(64,64,TextureFormat.RGBA32,false);for(int y=0;y<64;y++)for(int x=0;x<64;x++){float d=Vector2.Distance(new Vector2(x,y),new Vector2(31.5f,31.5f))/31.5f;splashTexture.SetPixel(x,y,new Color(1,1,1,Mathf.Clamp01((1-d)*5)));}splashTexture.Apply();}float alpha=Mathf.Clamp01((splashUntil-Time.time)/2.5f);for(int i=0;i<16;i++){float x=(.14f+(i*.237f)% .72f)*Screen.width,y=(.18f+(i*.179f)% .62f)*Screen.height;float size=Screen.height*(.035f+(i%4)*.013f)*(1.2f-alpha*.2f);GUI.color=new Color(.9f,.25f,.12f,alpha*.65f);GUI.DrawTexture(new Rect(x-size/2,y-size/2,size,size*1.3f),splashTexture);}GUI.color=new Color(.25f,.015f,.01f,.92f);GUI.DrawTexture(new Rect(Screen.width*.2f,Screen.height*.19f,Screen.width*.6f,65),Texture2D.whiteTexture);GUI.color=Color.white;var warning=new GUIStyle(GUI.skin.label){fontSize=20,alignment=TextAnchor.MiddleCenter,wordWrap=true};GUI.Label(new Rect(Screen.width*.2f,Screen.height*.19f,Screen.width*.6f,65),"GÖZLERİN ZARAR GÖRDÜ!\nKoruyucu gözlüğün takılı değil. Eğitim gösterimi • F6: sıfırla",warning);}
 void OnDestroy(){if(splashTexture)Destroy(splashTexture);if(wornCoat)Destroy(wornCoat);}
}
}

